from dataclasses import dataclass
from pathlib import Path


@dataclass(slots=True, frozen=True)
class LoadDataResult:
    records: list[dict[str, object]]
    skipped: int
    error: str | None = None


def load_json_lines(file_path: Path | str) -> LoadDataResult:
    """Parse JSON lines from a file, skipping malformed lines and tracking counts."""
    path = Path(file_path)
    skipped = 0
    records = []
    try:
        with path.open(mode="r", encoding="utf-8", newline="\n") as fh:
            for line in fh:
                line = line.rstrip("\r\n")
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                    if isinstance(obj, dict):
                        records.append(obj)
                except json.JSONDecodeError:
                    skipped += 1
    except OSError as exc:
        return LoadDataResult(records=[], skipped=skipped, error=str(exc))
    return LoadDataResult(records=records, skipped=skipped)
```

